/** Draws the sidebar off screen with a busy raid in it. The picture lands in build/panel.png. */
public class CoxStoragePanelTest
{
	private static final CoxStoragePanel.Actions NO_ACTIONS = new CoxStoragePanel.Actions()
	{
		@Override
		public void setNeed(Potion potion, int doses)
		{
		}

		@Override
		public void setNeedsTab(boolean solo)
		{
		}

		@Override
		public void renameChest(String key, String name)
		{
		}

		@Override
		public void setChestOrdered(String key, boolean ordered)
		{
		}

		@Override
		public void setChestLines(String key, boolean deposit, String text)
		{
		}

		@Override
		public void setMarking(boolean on)
		{
		}

		@Override
		public void selectChest(String key)
		{
		}

		@Override
		public void deleteChest(String key)
		{
		}

		@Override
		public void copyLoadout(String key)
		{
		}

		@Override
		public void copyChestFromOther(String key)
		{
		}
	};

	private static PanelState busyRaid()
	{
		PanelState state = new PanelState();
		state.inParty = true;
		state.inventory = Supplies.of(new int[]{4, 8, 4, 0});
		state.privateStorage = Supplies.of(new int[]{0, 4, 0, 4});
		state.solo = true;
		state.separateSoloChests = true;
		state.units = NeedUnits.POTIONS;
		Needs needs = Needs.soloDefaults();
		for (Potion potion : Potion.values())
		{
			state.need.put(potion, state.applies(potion) ? needs.get(potion) : 0);
		}
		ChestPlan ice = state.chests.getOrCreate("RAIDS_ICE_DEMON#1", "Ice Demon");
		ice.getDeposit().add("Elder maul");
		ChestPlan farm = state.chests.getOrCreate("RAIDS_FARMING#1", "Farming 1");
		farm.getDeposit().add("everything");
		farm.getWithdraw().addAll(Arrays.asList("Xeric's aid, 2", "Stinkhorn mushroom, 3", "Noxifer"));
		farm.setOrdered(true);
		state.currentChest = "RAIDS_FARMING#1";
		state.marking = true;
		state.carriedItems = ChestProgress.tally(Arrays.asList("Xeric's aid(4)", "Xeric's aid(3)", "Stinkhorn mushroom"));

		PanelState.Member me = new PanelState.Member();
		me.name = "brizzy";
		me.self = true;
		me.status = new MemberSupplies(Supplies.of(new int[]{4, 12, 4, 4}), null, null);
		PanelState.Member bob = new PanelState.Member();
		bob.name = "Zezima the 2nd";
		bob.status = new MemberSupplies(Supplies.of(new int[]{4, 8, 4, 4}),
			Supplies.of(new int[]{4, 0, 4, 4}), Supplies.of(new int[]{4, 16, 0, 0}));
		PanelState.Member quiet = new PanelState.Member();
		quiet.name = "No Plugin";
		state.team.addAll(Arrays.asList(me, bob, quiet));
		return state;
	}

	private static void layOut(Component component)
	{
		component.doLayout();
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				layOut(child);
			}
		}
	}

	private static int deepestRightEdge(Component component, int offset)
	{
		int edge = component.isVisible() ? offset + component.getX() + component.getWidth() : 0;
		if (component instanceof Container && component.isVisible())
		{
			for (Component child : ((Container) component).getComponents())
			{
				edge = Math.max(edge, deepestRightEdge(child, offset + component.getX()));
			}
		}
		return edge;
	}

	@Test
	public void drawsABusyRaidWithinTheSidebarWidth() throws Exception
	{
		draw("build/panel.png");
	}

	private static void draw(String file) throws Exception
	{
		BufferedImage[] drawn = new BufferedImage[1];
		int[] rightEdge = new int[1];
		SwingUtilities.invokeAndWait(() ->
		{
			CoxStoragePanel panel = new CoxStoragePanel(NO_ACTIONS, (label, itemId) ->
			{
				BufferedImage square = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
				Graphics2D g = square.createGraphics();
				g.setColor(new Color(itemId * 9973 % 0xffffff));
				g.fillRoundRect(10, 4, 16, 24, 6, 6);
				g.dispose();
				label.setIcon(new ImageIcon(square));
			});
			panel.update(busyRaid());

			// twice, html labels only know their height once they have a width
			for (int pass = 0; pass < 2; pass++)
			{
				Dimension size = panel.getPreferredSize();
				panel.setSize(PluginPanel.PANEL_WIDTH, size.height);
				layOut(panel);
			}

			BufferedImage image = new BufferedImage(panel.getWidth(), panel.getHeight(), BufferedImage.TYPE_INT_RGB);
			Graphics2D g = image.createGraphics();
			panel.paint(g);
			g.dispose();
			drawn[0] = image;
			rightEdge[0] = deepestRightEdge(panel, -panel.getX());
		});

		File out = new File(file);
		out.getParentFile().mkdirs();
		ImageIO.write(drawn[0], "png", out);

		assertEquals(PluginPanel.PANEL_WIDTH, drawn[0].getWidth());
		assertTrue("taller than it should be: " + drawn[0].getHeight(), drawn[0].getHeight() < 2500);
		assertTrue("something sticks out to x=" + rightEdge[0], rightEdge[0] <= PluginPanel.PANEL_WIDTH);
	}
}

package com.coxstorageplanner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class SuppliesTest
{
	@Test
	public void dosesFollowTheItemId()
	{
		// overload (-)(1), overload (4), overload (+)(1), overload (+)(4)
		assertEquals(1, Potion.OVERLOAD.doses(20985));
		assertEquals(4, Potion.OVERLOAD.doses(20992));
		assertEquals(1, Potion.OVERLOAD.doses(20993));
		assertEquals(4, Potion.OVERLOAD.doses(20996));
		assertEquals(0, Potion.OVERLOAD.doses(20997));
		assertEquals(0, Potion.OVERLOAD.doses(20984));
	}

	@Test
	public void everyIdBelongsToOnePotion()
	{
		assertEquals(Potion.XERICS_AID, Potion.of(20984));
		assertEquals(Potion.REVITALISATION, Potion.of(20957));
		assertEquals(Potion.PRAYER_ENHANCE, Potion.of(20969));
		assertEquals(Potion.ELDER, Potion.of(20921));
		assertEquals(Potion.TWISTED, Potion.of(20933));
		assertEquals(Potion.KODAI, Potion.of(20945));
		// the nmz overload is a different potion
		assertNull(Potion.of(11730));
		assertNull(Potion.of(-1));
	}

	@Test
	public void countsDosesAcrossAContainer()
	{
		// xeric's aid (+)(4), xeric's aid (+)(2), overload (+)(3), a shark, an empty slot
		Supplies supplies = Supplies.count(new int[]{20984, 20982, 20995, 385, -1}, new int[]{1, 1, 1, 1, 0});
		assertEquals(6, supplies.doses(Potion.XERICS_AID));
		assertEquals(3, supplies.doses(Potion.OVERLOAD));
		assertEquals(0, supplies.doses(Potion.REVITALISATION));
	}

	@Test
	public void aSplitOverloadIsOnlyAsBigAsItsSmallestPart()
	{
		// elder (+)(4), twisted (+)(4), kodai (+)(3)
		Supplies set = Supplies.count(new int[]{20924, 20936, 20947}, new int[]{1, 1, 1});
		assertEquals(3, set.splitOverloadDoses());
		// no kodai, no overload
		assertEquals(0, Supplies.count(new int[]{20924, 20936}, new int[]{1, 1}).splitOverloadDoses());
		assertNull(Potion.of(-1));
		assertEquals(0, Potion.SPLIT_OVERLOAD.doses(-1));
	}

	@Test
	public void addsUp()
	{
		Supplies a = Supplies.count(new int[]{20996}, new int[]{1});
		Supplies b = Supplies.count(new int[]{20994, 20960}, new int[]{1, 1});
		assertEquals(6, a.plus(b).doses(Potion.OVERLOAD));
		assertEquals(4, a.plus(b).doses(Potion.REVITALISATION));
	}

	@Test
	public void toleratesShortOrHostileArrays()
	{
		assertEquals(Supplies.EMPTY, Supplies.of(null));
		assertEquals(5, Supplies.of(new int[]{5}).doses(Potion.OVERLOAD));
		assertEquals(0, Supplies.of(new int[]{-5}).doses(Potion.OVERLOAD));
		assertEquals(0, Supplies.of(new int[40]).doses(Potion.KODAI));
	}
}

package com.coxstorageplanner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class NeedsTest
{
	@Test
	public void defaultsForNeverStored()
	{
		Needs needs = Needs.defaults();
		assertEquals(24, needs.get(Potion.XERICS_AID));
		assertEquals(0, needs.get(Potion.STAMINA));
		assertEquals(4, Needs.soloDefaults().get(Potion.STAMINA));
		assertEquals(needs.encode(), Needs.parse("", Needs.defaults()).encode());
		assertEquals(needs.encode(), Needs.parse(null, Needs.defaults()).encode());
	}

	@Test
	public void emptyIsNotTheSameAsNeverSet()
	{
		Needs needs = Needs.defaults();
		for (Potion potion : Potion.values())
		{
			needs.set(potion, 0);
		}
		assertEquals("none", needs.encode());
		assertEquals(0, Needs.parse(needs.encode(), Needs.defaults()).get(Potion.OVERLOAD));
	}

	@Test
	public void survivesTheConfigRoundTripAndJunk()
	{
		Needs needs = new Needs();
		needs.set(Potion.REVITALISATION, 3);
		needs.set(Potion.OVERLOAD, 500);
		Needs loaded = Needs.parse(needs.encode() + ",BEER:1,OVERLOAD,x", Needs.defaults());
		assertEquals(3, loaded.get(Potion.REVITALISATION));
		assertEquals(Needs.MAX_DOSES, loaded.get(Potion.OVERLOAD));
		assertEquals(needs.encode(), loaded.encode());
	}

	@Test
	public void readsThePerRoomFormOfTheFirstVersion()
	{
		Needs loaded = Needs.parse("TEKTON:OVERLOAD:1,OLM:OVERLOAD:4,OLM:XERICS_AID:12", Needs.defaults());
		assertEquals(5, loaded.get(Potion.OVERLOAD));
		assertEquals(12, loaded.get(Potion.XERICS_AID));
	}

	@Test
	public void reportsWhetherAnythingChanged()
	{
		Needs needs = new Needs();
		assertFalse(needs.set(Potion.OVERLOAD, 0));
		assertTrue(needs.set(Potion.OVERLOAD, 2));
		assertFalse(needs.set(Potion.OVERLOAD, 2));
		needs.set(Potion.OVERLOAD, -5);
		assertEquals(0, needs.get(Potion.OVERLOAD));
	}
}

package com.coxstorageplanner;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class NeedUnitsTest
{
	@Test
	public void formatsDosesAsPotions()
	{
		assertEquals("6", NeedUnits.POTIONS.format(24));
		assertEquals("2.25", NeedUnits.POTIONS.format(9));
		assertEquals("0.5", NeedUnits.POTIONS.format(2));
		assertEquals("0", NeedUnits.POTIONS.format(0));
		assertEquals("9", NeedUnits.DOSES.format(9));
	}

	@Test
	public void parsesWhatItFormats()
	{
		assertEquals(24, NeedUnits.POTIONS.parse("6"));
		assertEquals(9, NeedUnits.POTIONS.parse(" 2.25 "));
		assertEquals(6, NeedUnits.POTIONS.parse("1.5"));
		assertEquals(9, NeedUnits.DOSES.parse("9"));
		assertEquals(0, NeedUnits.DOSES.parse("six"));
		assertEquals(0, NeedUnits.POTIONS.parse(""));
	}
}

package com.coxstorageplanner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class PanelStateTest
{
	private static Supplies overloads(int doses)
	{
		return Supplies.of(new int[]{doses});
	}

	@Test
	public void shortfallCountsInventoryAndPrivateStorage()
	{
		PanelState state = new PanelState();
		state.need.put(Potion.OVERLOAD, 12);
		state.inventory = overloads(4);
		assertEquals(8, state.shortfall(Potion.OVERLOAD));
		state.privateStorage = overloads(4);
		assertEquals(4, state.shortfall(Potion.OVERLOAD));
	}

	@Test
	public void sharedOnlyCountsWhenAsked()
	{
		PanelState state = new PanelState();
		state.need.put(Potion.OVERLOAD, 12);
		state.sharedStorage = overloads(8);
		assertEquals(12, state.shortfall(Potion.OVERLOAD));
		state.countShared = true;
		assertEquals(4, state.shortfall(Potion.OVERLOAD));
	}

	@Test
	public void splitOverloadsCountAsOverload()
	{
		PanelState state = new PanelState();
		state.need.put(Potion.OVERLOAD, 12);
		state.countSplit = true;
		state.inventory = overloads(4);
		// elder in the inventory, twisted and kodai in private storage
		state.inventory = state.inventory.plus(Supplies.count(new int[]{20924}, new int[]{1}));
		state.privateStorage = Supplies.count(new int[]{20936, 20948}, new int[]{1, 1});
		assertEquals(8, state.have(Potion.OVERLOAD));
		assertEquals(4, state.shortfall(Potion.OVERLOAD));

		state.countSplit = false;
		assertEquals(4, state.have(Potion.OVERLOAD));
	}

	@Test
	public void neverNegative()
	{
		PanelState state = new PanelState();
		state.need.put(Potion.OVERLOAD, 4);
		state.inventory = overloads(40);
		assertEquals(0, state.shortfall(Potion.OVERLOAD));
		assertEquals(0, state.shortfall(Potion.KODAI));
	}

	@Test
	public void partyMessageWithoutStoragesIsFine()
	{
		MemberSupplies status = MemberSupplies.from(new CoxStorageMessage(new int[]{8, 12}, null, null));
		assertEquals(12, status.getCarried().doses(Potion.XERICS_AID));
		assertEquals(12, status.getHeld().doses(Potion.XERICS_AID));
		assertNull(status.getStored());
		assertNull(status.getShared());
		assertEquals(Supplies.EMPTY, MemberSupplies.from(new CoxStorageMessage()).getCarried());
	}

	@Test
	public void sharedStorageComesFromAPartyMemberWhenYouHaveNotOpenedIt()
	{
		PanelState state = new PanelState();
		assertNull(state.shared());
		PanelState.Member bob = new PanelState.Member();
		bob.name = "Bob";
		bob.status = new MemberSupplies(Supplies.EMPTY, null, overloads(8));
		state.team.add(bob);
		assertEquals(8, state.shared().doses(Potion.OVERLOAD));
		state.sharedStorage = overloads(4);
		assertEquals(4, state.shared().doses(Potion.OVERLOAD));
	}
}

package com.coxstorageplanner;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class ChestPlanTest
{
	@Test
	public void linesMatchFromTheStartWithACount()
	{
		ChestPlan.Line aid = new ChestPlan.Line("Xeric's aid");
		assertTrue(aid.matches("Xeric's aid(4)"));
		assertTrue(aid.matches("xeric's aid(1)"));
		assertFalse(aid.matches("Overload(4)"));
		ChestPlan.Line shrooms = new ChestPlan.Line("Stinkhorn mushroom, 3");
		ChestPlan.Line old = new ChestPlan.Line("Stinkhorn mushroom x3");
		assertEquals(3, old.count);
		assertEquals("Stinkhorn mushroom", old.name);
		assertEquals("Wilson, sr.", new ChestPlan.Line("Wilson, sr.").name);
		assertEquals("Stinkhorn mushroom", shrooms.name);
		assertEquals(3, shrooms.count);
		ChestPlan.Line axe = new ChestPlan.Line("Dragon axe");
		assertEquals(1, axe.count);
		assertTrue(new ChestPlan.Line("everything").everything);
		assertTrue(new ChestPlan.Line("Everything").matches("anything at all"));
	}

	@Test
	public void wildcardsMatchTheWholeName()
	{
		ChestPlan.Line chins = new ChestPlan.Line("*chinchompa");
		assertTrue(chins.matches("Black chinchompa"));
		assertTrue(chins.matches("Chinchompa"));
		assertFalse(chins.matches("Chinchompa gloves"));
		ChestPlan.Line dragon = new ChestPlan.Line("Dragon *, 2");
		assertTrue(dragon.matches("Dragon axe"));
		assertFalse(dragon.matches("Dragonstone"));
		assertEquals(2, dragon.count);
		assertTrue(new ChestPlan.Line("Xeric's aid(?)").matches("Xeric's aid(4)"));
		assertFalse(new ChestPlan.Line("Xeric's aid(?)").matches("Xeric's aid(+)(4)"));
	}

	@Test
	public void aCountedDepositIsDoneOnceThatManyWentIn()
	{
		ChestPlan plan = new ChestPlan("RAIDS_FARMING#1", "Farming 1");
		plan.getDeposit().add("Endarkened*, 2");
		Map<String, Integer> three = Collections.singletonMap("Endarkened juice", 3);
		Map<String, Integer> one = Collections.singletonMap("Endarkened juice", 1);
		Map<String, Integer> none = Collections.emptyMap();
		assertFalse(new ChestProgress(plan, three, three, none).deposits.get(0).done);
		assertTrue(new ChestProgress(plan, one, three, none).deposits.get(0).done);
		assertTrue(new ChestProgress(plan, three, three, Collections.singletonMap("Endarkened juice", 2)).deposits.get(0).done);
		assertFalse(new ChestProgress(plan, three, three, one).deposits.get(0).done);
		// without a number every one of them goes in
		plan.getDeposit().set(0, "Endarkened*");
		assertFalse(new ChestProgress(plan, one, three, three).deposits.get(0).done);
		assertTrue(new ChestProgress(plan, none, three, none).deposits.get(0).done);
	}

	@Test
	public void markingCountsClicksPerItem()
	{
		List<String> lines = new ArrayList<>(Collections.singletonList("*chinchompa"));
		assertTrue(ChestPlan.mark(lines, "Xeric's aid(4)", 1));
		assertTrue(ChestPlan.mark(lines, "Xeric's aid(3)", 1));
		assertTrue(ChestPlan.mark(lines, "Black chinchompa", 1));
		assertEquals(Arrays.asList("*chinchompa", "Xeric's aid, 2", "Black chinchompa"), lines);
		assertTrue(ChestPlan.mark(lines, "Xeric's aid(2)", -1));
		assertTrue(ChestPlan.mark(lines, "Black chinchompa", -1));
		assertEquals(Arrays.asList("*chinchompa", "Xeric's aid"), lines);
		assertFalse(ChestPlan.mark(lines, "Elder maul", -1));
		assertEquals(Arrays.asList("*chinchompa", "Xeric's aid"), lines);
	}

	@Test
	public void typedTextBecomesTrimmedLines()
	{
		assertEquals(Arrays.asList("Elder maul", "Overload"), ChestPlan.lines("  Elder maul \n\n Overload\n"));
		assertTrue(ChestPlan.lines(null).isEmpty());
	}

	@Test
	public void progressTicksOffWhatIsInTheInventory()
	{
		ChestPlan plan = new ChestPlan("RAIDS_FARMING#1", "Farming 1");
		plan.getDeposit().add("Elder maul");
		plan.getWithdraw().addAll(Arrays.asList("Xeric's aid, 2", "Stinkhorn mushroom", "Overload"));
		plan.setOrdered(true);

		ChestProgress before = new ChestProgress(plan, ChestProgress.tally(Arrays.asList("Elder maul", "Xeric's aid(4)")));
		assertFalse(before.deposits.get(0).done);
		assertFalse(before.withdrawals.get(0).done);
		assertEquals("Xeric's aid, 2", before.next().line.text);
		assertTrue(before.highlightsDeposit("Elder maul"));
		assertFalse(before.highlightsDeposit("Overload(4)"));
		// the maul has to go in before the take-outs light
		assertNull(before.highlightsWithdraw("Xeric's aid(3)", 1));
		assertFalse(before.isDone());

		ChestProgress maulIn = new ChestProgress(plan, ChestProgress.tally(Arrays.asList("Xeric's aid(4)")));
		assertEquals(1, maulIn.highlightsWithdraw("Xeric's aid(3)", 1).order);
		assertNull(maulIn.highlightsWithdraw("Overload(4)", 1));
		assertNull(maulIn.highlightsWithdraw("Overload(4)", 2));
		assertEquals(3, maulIn.highlightsWithdraw("Overload(4)", 3).order);
		assertEquals(2, maulIn.rank(maulIn.highlightsWithdraw("Overload(4)", 3)));

		ChestProgress after = new ChestProgress(plan,
			ChestProgress.tally(Arrays.asList("Xeric's aid(4)", "Xeric's aid(4)", "Stinkhorn mushroom", "Overload(4)")));
		assertTrue(after.isDone());
		assertNull(after.next());
		assertNull(after.highlightsWithdraw("Overload(4)", Integer.MAX_VALUE));
	}

	@Test
	public void depositEverythingMeansAnEmptyInventory()
	{
		ChestPlan plan = new ChestPlan("RAIDS_ICE_DEMON#1", "Ice demon");
		plan.getDeposit().add("everything");
		assertFalse(new ChestProgress(plan, Collections.singletonMap("Bronze dagger", 1)).isDone());
		assertTrue(new ChestProgress(plan, Collections.emptyMap()).isDone());
		assertTrue(new ChestProgress(plan, Collections.singletonMap("Bronze dagger", 1)).highlightsDeposit("Bronze dagger"));
	}

	@Test
	public void unorderedPlansHaveNoNext()
	{
		ChestPlan plan = new ChestPlan("k", "n");
		plan.getWithdraw().add("Overload");
		assertNull(new ChestProgress(plan, Collections.emptyMap()).next());
	}

	/** An instance template chunk the way the client packs it. */
	private static int chunk(int templateX, int templateY, int plane)
	{
		return plane << 24 | (templateX / 8) << 14 | (templateY / 8) << 3;
	}

	@Test
	public void roomsComeFromTheTemplateChunk()
	{
		assertEquals("RAIDS_END", CoxStoragePlannerPlugin.roomType(chunk(3264, 5152, 0)));
		// the End room that leads down to Olm sits past the width the API gives End
		assertEquals("RAIDS_END", CoxStoragePlannerPlugin.roomType(chunk(3264 + 72, 5152 + 16, 0)));
		assertEquals("RAIDS_FARMING", CoxStoragePlannerPlugin.roomType(chunk(3264, 5440, 0)));
		assertEquals("RAIDS_FARMING", CoxStoragePlannerPlugin.roomType(chunk(3264 + 40, 5440 + 8, 1)));
		assertEquals("RAIDS_TIGHTROPE", CoxStoragePlannerPlugin.roomType(chunk(3264, 5344, 1)));
		assertEquals("RAIDS_VESPULA", CoxStoragePlannerPlugin.roomType(chunk(3264, 5280, 2)));
		assertNull(CoxStoragePlannerPlugin.roomType(chunk(3264, 5184, 0)));
		assertNull(CoxStoragePlannerPlugin.roomType(chunk(3264 + 96, 5152, 0)));
		assertNull(CoxStoragePlannerPlugin.roomType(-1));
		assertEquals("Pre-Olm", CoxStoragePlannerPlugin.chestName("RAIDS_END#2"));
		assertEquals("Pre-Vanguards", CoxStoragePlannerPlugin.chestName("RAIDS_END#1"));
		ChestBook book = new ChestBook();
		for (String key : new String[]{"RAIDS_END#2", "RAIDS_FARMING#2", "RAIDS_SCAVENGERS#1", "RAIDS_ICE_DEMON#1", "RAIDS_END#1"})
		{
			book.getOrCreate(key, CoxStoragePlannerPlugin.chestName(key));
		}
		List<String> ordered = new ArrayList<>();
		for (ChestPlan plan : CoxStoragePlannerPlugin.inRaidOrder(book.all()))
		{
			ordered.add(plan.getName());
		}
		assertEquals(Arrays.asList("Ice Demon", "Pre-Vanguards", "Farming 2", "Pre-Olm", "Scavengers 1"), ordered);
