		overlayManager.add(chestMarkerOverlay);

		wsClient.registerMessage(CoxStorageMessage.class);

		inventoryDirty = true;
		resendStatus = true;
		refresh();
	}

	@Override
	protected void shutDown()
	{
		wsClient.unregisterMessage(CoxStorageMessage.class);
		overlayManager.remove(chestOverlay);
		overlayManager.remove(chestItemOverlay);
		overlayManager.remove(chestMarkerOverlay);
		storageUnits.clear();
		clientToolbar.removeNavigation(navigationButton);
		panel = null;
		navigationButton = null;

		roomKeys.clear();
		lastRoomSlot = null;
		currentChest = null;
		openChest = null;
		itemNames.clear();
		marking = false;
		synchronized (lock)
		{
			members.clear();
			inventory = Supplies.EMPTY;
			privateStorage = null;
			sharedStorage = null;
			inventoryItems = Collections.emptyMap();
		}
		privateItems.clear();
		lastInventory.clear();
		openStorage = 0;
		inRaid = false;
		lastSent = null;
	}

