	// ---- game state ----

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		switch (event.getContainerId())
		{
			case InventoryID.INV:
				inventoryChanged(event.getItemContainer().getItems());
				inventoryDirty = true;
				break;
			case InventoryID.RAIDS_PRIVATESTORAGE:
				if (inRaid)
				{
					privateItems.clear();
					for (Item item : event.getItemContainer().getItems())
					{
						if (item.getId() > 0)
						{
							privateItems.merge(item.getId(), item.getQuantity(), Integer::sum);
							// named here, on the client thread, so the sidebar can tally the storage later
							itemName(item.getId());
						}
					}
					publishPrivateStorage();
					updateOpenChest();
				}
				break;
			case InventoryID.RAIDS_SHAREDSTORAGE:
				if (inRaid)
				{
					Supplies stored = count(event.getItemContainer().getItems());
					synchronized (lock)
					{
						sharedStorage = stored;
					}
					inventoryDirty = true;
					updateOpenChest();
				}
				break;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.RAIDS_STORAGE_PRIVATE || event.getGroupId() == InterfaceID.RAIDS_STORAGE_SHARED)
		{
			openStorage = event.getGroupId();
			synchronized (lock)
			{
				openedWith = inventoryItems;
			}
			String key = currentChest;
			if (key != null)
			{
				openedWithByChest.put(key, openedWith);
				openedChests.add(key);
			}
			if (key != null && book().get(key) == null && book().getOrCreate(key, chestName(key)) != null)
			{
				saveChests();
			}
			updateOpenChest();
			refresh();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == openStorage)
		{
			// a deposit made as the interface closes still shows up in the inventory this tick or the next
			closedStorage = openStorage;
			closedStorageUntil = client.getTickCount() + 1;
			openStorage = 0;
			openChest = null;
		}
	}

	/** Puts "Mark" on top of an item's menu while marking, so a left click adds it to the chest's list. */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!marking)
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (MenuEntry entry : entries)
		{
			int itemId = entry.getItemId();
			if (itemId <= 0 || entry.getType() == MenuAction.RUNELITE)
			{
				continue;
			}
			int group = entry.getParam1() >> 16;
			boolean deposit;
			String key;
			if (group == InterfaceID.RAIDS_STORAGE_PRIVATE || group == InterfaceID.RAIDS_STORAGE_SHARED)
			{
				deposit = false;
				key = activeChest();
			}
			else if (group == InterfaceID.RAIDS_STORAGE_SIDE)
			{
				deposit = true;
				key = activeChest();
			}
			else if (group == InterfaceID.INVENTORY && openStorage == 0)
			{
				deposit = true;
				key = selectedChest;
			}
			else
			{
				continue;
			}
			if (key == null)
			{
				return;
			}
			String target = entry.getTarget();
			String list = deposit ? "put in" : "take out";
			client.getMenu().createMenuEntry(-1)
				.setOption("Unmark " + list)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> markItem(key, deposit, itemId, -1));
			client.getMenu().createMenuEntry(-1)
				.setOption("Mark " + list)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> markItem(key, deposit, itemId, 1));
			return;
		}
	}

	private void markItem(String key, boolean deposit, int itemId, int delta)
	{
		ChestPlan plan = book().getOrCreate(key, chestName(key));
		if (plan != null && ChestPlan.mark(deposit ? plan.getDeposit() : plan.getWithdraw(), itemName(itemId), delta))
		{
			saveChests();
			updateOpenChest();
			refresh();
		}
	}

	/**
	 * The game only sends a storage's contents while its interface is open, so a deposit made as it
	 * closes never arrives. What left the inventory went into the storage, so it's added here.
	 */
	private void inventoryChanged(Item[] items)
	{
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : items)
		{
			if (item.getId() > 0)
			{
				now.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		int storage = openStorage != 0 ? openStorage : client.getTickCount() <= closedStorageUntil ? closedStorage : 0;
		if (storage != 0 && inRaid && !lastInventory.isEmpty())
		{
			Map<Integer, Integer> moved = new HashMap<>();
			for (Map.Entry<Integer, Integer> e : lastInventory.entrySet())
			{
				int delta = e.getValue() - now.getOrDefault(e.getKey(), 0);
				if (delta != 0)
				{
					moved.put(e.getKey(), delta);
				}
			}
			for (Map.Entry<Integer, Integer> e : now.entrySet())
			{
				if (!lastInventory.containsKey(e.getKey()))
				{
					moved.put(e.getKey(), -e.getValue());
				}
			}
			if (!moved.isEmpty())
			{
				storageChanged(storage, moved);
			}
		}
		lastInventory.clear();
		lastInventory.putAll(now);
	}

	/** @param moved item id to the count that went into the storage, negative for what came out */
	private void storageChanged(int storage, Map<Integer, Integer> moved)
	{
		if (storage == InterfaceID.RAIDS_STORAGE_PRIVATE)
		{
			for (Map.Entry<Integer, Integer> e : moved.entrySet())
			{
				int quantity = privateItems.getOrDefault(e.getKey(), 0) + e.getValue();
				if (quantity > 0)
				{
					privateItems.put(e.getKey(), quantity);
				}
				else
				{
					privateItems.remove(e.getKey());
				}
			}
			publishPrivateStorage();
		}
		else
		{
			Supplies shared;
			synchronized (lock)
			{
				shared = sharedStorage;
			}
			if (shared == null)
			{
				return;
			}
			int[] doses = shared.toArray();
			for (Map.Entry<Integer, Integer> e : moved.entrySet())
			{
				Potion potion = Potion.of(e.getKey());
				if (potion != null)
				{
					doses[potion.ordinal()] += potion.doses(e.getKey()) * e.getValue();
				}
			}
			Supplies changed = Supplies.of(doses);
			synchronized (lock)
			{
				sharedStorage = changed;
			}
			inventoryDirty = true;
		}
	}

	private void publishPrivateStorage()
	{
		Supplies stored = count(privateItems);
		synchronized (lock)
		{
			privateStorage = stored;
		}
		inventoryDirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		boolean changed = false;

		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
		{
			ticksOutside = 0;
			if (!inRaid)
			{
				inRaid = true;
				raidSoloOverride = null;
				// what the client still holds is from an earlier raid until the storage is opened
				inventoryDirty = true;
			}
			boolean soloNow = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE) <= 1;
			if (soloNow != soloRaid)
			{
				soloRaid = soloNow;
				changed = true;
			}
			trackRoom();
		}
		else if (inRaid && ++ticksOutside >= LEAVE_TICKS)
		{
			inRaid = false;
			leftRaid();
			changed = true;
		}

		if (inventoryDirty)
		{
			inventoryDirty = false;
			recompute();
			changed = true;
		}
		if (changed)
		{
			refresh();
		}
		sendToParty();
	}

	/**
	 * Works out which chest the player is at. A room is its template (RAIDS_FARMING, RAIDS_ICE_DEMON...)
	 * and the two rooms of the same template are told apart by which came first this raid, which
	 * is fixed in Challenge Mode. The floors are on different planes (first floor 3, second floor 2),
	 * so the End and Farming rooms are numbered by floor. Room slots are 32x32 tile squares of the
	 * instance; walking within a room that straddles two squares keeps the same key. Ground the table
	 * doesn't know counts as the room before it.
	 */
	private static boolean isStorageUnit(int id)
	{
		return id == ObjectID.RAIDS_STORAGE_1 || id == ObjectID.RAIDS_STORAGE_2 || id == ObjectID.RAIDS_STORAGE_3;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		int id = event.getGameObject().getId();
		// a storage unit is built on a hotspot, which a varbit turns into the small, medium or large one
		if (isStorageUnit(id) || id == ObjectID.RAIDS_STORAGE_HOTSPOT)
		{
			storageUnits.add(event.getGameObject());
		}
	}

	/** Whether an object is a built storage unit right now, looking through a hotspot to what it shows. */
	private boolean isBuiltStorage(GameObject object)
	{
		ObjectComposition def = client.getObjectDefinition(object.getId());
		if (def != null && def.getImpostorIds() != null)
		{
			def = def.getImpostor();
		}
		return def != null && isStorageUnit(def.getId());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		storageUnits.remove(event.getGameObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			storageUnits.clear();
		}
	}

	List<GameObject> getStorageUnits()
	{
		return storageUnits;
	}

	/**
	 * Whether the chest for a storage unit is all done, null when it's not in the current room or
	 * has no plan. The one in the room is the one in the same 32-tile square as the player, or the
	 * open storage, whichever.
	 */
	Boolean chestDoneAt(GameObject storage)
	{
		Player player = client.getLocalPlayer();
		String key = currentChest;
		if (player == null || key == null)
		{
			return null;
		}
		WorldPoint here = player.getWorldLocation();
		WorldPoint there = storage.getWorldLocation();
		if (there.getPlane() != here.getPlane() || Math.floorDiv(there.getX(), 32) != Math.floorDiv(here.getX(), 32)
			|| Math.floorDiv(there.getY(), 32) != Math.floorDiv(here.getY(), 32) || !isBuiltStorage(storage))
		{
			return null;
		}
		ChestProgress progress = progressFor(key);
		return progress == null ? null : progress.isDone();
	}

	/**
	 * A chest's progress: the open storage's when that's the one, else judged from the inventory, and
	 * from the private storage's tracked contents if it has been opened here this raid. Null without a plan.
	 */
	private ChestProgress progressFor(String key)
	{
		ChestProgress progress = openChest;
		if (progress != null && progress.plan.getKey().equals(key))
		{
			return progress;
		}
		ChestPlan plan = book().get(key);
		if (plan == null || (plan.getDeposit().isEmpty() && plan.getWithdraw().isEmpty()))
		{
			return null;
		}
		Map<String, Integer> items;
		Map<String, Integer> worn;
		synchronized (lock)
		{
			items = inventoryItems;
			worn = wornItems;
		}
		boolean opened = openedChests.contains(key);
		Map<String, Integer> before = openedWithByChest.getOrDefault(key, items);
		return new ChestProgress(plan, items, worn, before, opened ? privateTally() : null, config.chestPutBack());
	}

	/** The private storage's tracked contents by item name. */
	private Map<String, Integer> privateTally()
	{
		Map<String, Integer> items = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : privateItems.entrySet())
		{
			items.merge(itemName(e.getKey()), e.getValue(), Integer::sum);
		}
		return items;
	}

	private void trackRoom()
	{
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (player == null || view == null || !view.isInstance())
		{
			currentChest = null;
			return;
		}
		LocalPoint local = player.getLocalLocation();
		int[][][] chunks = view.getInstanceTemplateChunks();
		int plane = view.getPlane();
		int chunkX = local.getSceneX() / 8;
		int chunkY = local.getSceneY() / 8;
		if (chunks == null || plane >= chunks.length || chunkX < 0 || chunkX >= chunks[plane].length
			|| chunkY < 0 || chunkY >= chunks[plane][chunkX].length)
		{
			currentChest = null;
			return;
		}
		int chunk = chunks[plane][chunkX][chunkY];
		String room = roomType(chunk);
		if (room == null)
		{
			if (chunk != -1 && inRaid && unknownChunks.add(chunk))
			{
				// so a room the table misses can be reported from the client log
				log.info("unknown raid room: template x={} y={} plane={} at plane {}", (chunk >> 14 & 0x3FF) * 8,
					(chunk >> 3 & 0x7FF) * 8, chunk >> 24 & 3, plane);
			}
			if (!inRaid)
			{
				currentChest = null;
			}
			// inside the raid a stretch the table doesn't know still belongs to the last room, so a
			// storage there (the one after the tightrope) goes on that room's chest
			return;
		}
		WorldPoint world = player.getWorldLocation();
		int slotX = Math.floorDiv(world.getX(), 32);
		int slotY = Math.floorDiv(world.getY(), 32);
		String slot = room + ":" + slotX + ":" + slotY + ":" + world.getPlane();
		String key = roomKeys.get(slot);
		if (key == null)
		{
			// the same room type next door is the same room across a square's edge
			if (lastRoomSlot != null && lastRoomSlot.startsWith(room + ":"))
			{
				String[] parts = lastRoomSlot.split(":");
				if (Math.abs(Integer.parseInt(parts[1]) - slotX) <= 1 && Math.abs(Integer.parseInt(parts[2]) - slotY) <= 1
					&& Integer.parseInt(parts[3]) == world.getPlane())
				{
					key = roomKeys.get(lastRoomSlot);
				}
			}
			if (key == null && FLOOR_ROOMS.contains(room) && floor(world.getPlane()) > 0)
			{
				// one per floor, so the floor is the number whatever order the plugin saw them in
				key = room + "#" + floor(world.getPlane());
			}
			if (key == null)
			{
				int n = 1;
				for (String seen : new HashSet<>(roomKeys.values()))
				{
					if (seen.startsWith(room + "#"))
					{
						n++;
					}
				}
				key = room + "#" + n;
			}
			roomKeys.put(slot, key);
		}
		lastRoomSlot = slot;
		if (!key.equals(currentChest))
		{
			currentChest = key;
			refresh();
		}
	}

	/** Room templates a Challenge Mode raid has more than one of, so the first is "End 1" not "End". */
	private static final Set<String> REPEATED_ROOMS = new HashSet<>(Arrays.asList(
		"RAIDS_END", "RAIDS_FARMING", "RAIDS_SCAVENGERS"));

	/** Rooms every floor has exactly one of, numbered by floor rather than by when they were first seen. */
	private static final Set<String> FLOOR_ROOMS = new HashSet<>(Arrays.asList("RAIDS_END", "RAIDS_FARMING"));

	/** The raid's first floor is on plane 3 and its second on plane 2; 0 for anything else (Olm, the lobby). */
	static int floor(int plane)
	{
		return plane == 3 ? 1 : plane == 2 ? 2 : 0;
	}

	/**
	 * The raid's room templates: template y and plane to room, from the API's InstanceTemplates. Every room is
	 * 96 tiles wide in the template (the API has End at 64, which misses the End room that leads down to
	 * Olm), and the second layouts of the farming and scavenger rooms are the same room.
	 */
	private static final Map<Integer, String> ROOMS = new HashMap<>();

	static
	{
		ROOMS.put(5696, "RAIDS_START");
		ROOMS.put(5152, "RAIDS_END");
		ROOMS.put(5216, "RAIDS_SCAVENGERS");
		ROOMS.put(5248, "RAIDS_SHAMANS");
		ROOMS.put(5280, "RAIDS_VASA");
		ROOMS.put(5312, "RAIDS_VANGUARDS");
		ROOMS.put(5344, "RAIDS_ICE_DEMON");
		ROOMS.put(5376, "RAIDS_THIEVING");
		ROOMS.put(5440, "RAIDS_FARMING");
		ROOMS.put(5216 + (1 << 16), "RAIDS_SCAVENGERS");
		ROOMS.put(5312 + (1 << 16), "RAIDS_MUTTADILES");
		ROOMS.put(5248 + (1 << 16), "RAIDS_MYSTICS");
		ROOMS.put(5280 + (1 << 16), "RAIDS_TEKTON");
		ROOMS.put(5344 + (1 << 16), "RAIDS_TIGHTROPE");
		ROOMS.put(5440 + (1 << 16), "RAIDS_FARMING");
		ROOMS.put(5248 + (2 << 16), "RAIDS_GUARDIANS");
		ROOMS.put(5280 + (2 << 16), "RAIDS_VESPULA");
		ROOMS.put(5344 + (2 << 16), "RAIDS_CRABS");
	}

	/** The room an instance template chunk belongs to, null outside the raid's rooms (and for the lobby). */
	static String roomType(int chunk)
	{
		if (chunk == -1)
		{
			return null;
		}
		int templateY = (chunk >> 3 & 0x7FF) * 8;
		int templateX = (chunk >> 14 & 0x3FF) * 8;
		int templatePlane = chunk >> 24 & 3;
		if (templateX < 3264 || templateX >= 3264 + 96)
		{
			return null;
		}
		return ROOMS.get((templateY & ~31) + (templatePlane << 16));
	}

	/**
	 * Moves chests saved under the old per-layout keys (RAIDS_FARMING2#1) to the room's key, dropping
	 * them if it's taken, and gives chests still carrying an old default name the current one.
	 */
	private void migrateChestKeys(ChestBook chests)
	{
		boolean changed = false;
		for (ChestPlan plan : chests.all())
		{
			if ((plan.getName().equals("End 1") || plan.getName().equals("End 2") || plan.getName().equals("End"))
				&& !plan.getName().equals(chestName(plan.getKey())))
			{
				plan.setName(chestName(plan.getKey()));
				changed = true;
			}
			String[] parts = plan.getKey().split("#", 2);
			if (parts.length == 2 && parts[0].endsWith("2"))
			{
				String key = parts[0].substring(0, parts[0].length() - 1) + "#" + parts[1];
				chests.remove(plan.getKey());
				if (chests.get(key) == null)
				{
					ChestPlan moved = chests.getOrCreate(key, chestName(key));
					moved.getDeposit().addAll(plan.getDeposit());
					moved.getWithdraw().addAll(plan.getWithdraw());
					moved.setOrdered(plan.isOrdered());
				}
				changed = true;
			}
		}
		if (changed)
		{
			saveChests();
		}
	}

	/** The Challenge Mode layout, which is fixed, so the sidebar can list chests in the order you reach them. */
	private static final List<String> RAID_ORDER = Arrays.asList(
		"RAIDS_START#1", "RAIDS_TEKTON#1", "RAIDS_CRABS#1", "RAIDS_ICE_DEMON#1", "RAIDS_FARMING#1", "RAIDS_SHAMANS#1",
		"RAIDS_END#1", "RAIDS_VANGUARDS#1", "RAIDS_THIEVING#1", "RAIDS_VESPULA#1", "RAIDS_FARMING#2",
		"RAIDS_TIGHTROPE#1", "RAIDS_GUARDIANS#1", "RAIDS_VASA#1", "RAIDS_MYSTICS#1", "RAIDS_MUTTADILES#1", "RAIDS_END#2");

	/** Where a chest comes in the raid, for sorting; rooms the layout doesn't place go after the rest, by key. */
	static int raidOrder(String key)
	{
		int index = RAID_ORDER.indexOf(key);
		return index < 0 ? RAID_ORDER.size() : index;
	}

	/** Chests in the order the raid reaches them. */
	static List<ChestPlan> inRaidOrder(List<ChestPlan> plans)
	{
		List<ChestPlan> sorted = new ArrayList<>(plans);
		sorted.sort(Comparator.comparingInt((ChestPlan plan) -> raidOrder(plan.getKey())).thenComparing(ChestPlan::getKey));
		return sorted;
	}

	/** "Farming 2", "Pre-Vanguards", "Ice Demon" from a key like RAIDS_FARMING#2. */
	static String chestName(String key)
	{
		if (key.equals("RAIDS_END#1"))
		{
			// the End rooms are named for what's next, since that's what you're packing for
			return "Pre-Vanguards";
		}
		if (key.equals("RAIDS_END#2"))
		{
			return "Pre-Olm";
		}
		String[] parts = key.substring("RAIDS_".length()).split("#");
		String[] words = parts[0].toLowerCase(Locale.ROOT).split("_");
		StringBuilder name = new StringBuilder();
		for (String word : words)
		{
			name.append(name.length() == 0 ? "" : " ").append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
		}
		if (name.toString().endsWith("2"))
		{
			name.setLength(name.length() - 1);
		}
		String number = parts.length > 1 ? parts[1] : "1";
		boolean several = REPEATED_ROOMS.contains("RAIDS_" + parts[0]) || !number.equals("1");
		return several ? name + " " + number : name.toString();
	}

	private void saveChests()
	{
		configManager.setConfiguration(CoxStoragePlannerConfig.GROUP, CoxStoragePlannerConfig.KEY_CHESTS, chests.encode(gson));
		configManager.setConfiguration(CoxStoragePlannerConfig.GROUP, CoxStoragePlannerConfig.KEY_CHESTS_SOLO, chestsSolo.encode(gson));
	}

	/** The chest plans in use: the solo ones in a solo raid (or on the Solo switch) when kept apart, else the team ones. */
	private ChestBook book()
	{
		return separateChests() && solo() ? chestsSolo : chests;
	}

	private boolean separateChests()
	{
		return config.separateSoloChests();
	}

	/** The chest a storage in front of the player belongs to: the room's, or the sidebar's when the room isn't known. */
	private String activeChest()
	{
		return currentChest != null ? currentChest : selectedChest;
	}

	/** Recomputes the progress the overlays show, on the client thread. */
	private void updateOpenChest()
	{
		ChestPlan plan = openStorage == 0 ? null : book().get(activeChest());
		if (plan == null)
		{
			openChest = null;
			return;
		}
		Map<String, Integer> items;
		Map<String, Integer> worn;
		Map<String, Integer> before;
		synchronized (lock)
		{
			items = inventoryItems;
			worn = wornItems;
			before = openedWith;
		}
		ItemContainer storage = client.getItemContainer(openStorage == InterfaceID.RAIDS_STORAGE_SHARED
			? InventoryID.RAIDS_SHAREDSTORAGE : InventoryID.RAIDS_PRIVATESTORAGE);
		openChest = new ChestProgress(plan, items, worn, before, tally(storage), config.chestPutBack());
	}

	/** Item name to quantity for a container, null for one the client hasn't seen. */
	private Map<String, Integer> tally(ItemContainer container)
	{
		if (container == null)
		{
			return null;
		}
		Map<String, Integer> items = new LinkedHashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				items.merge(itemName(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return items;
	}

	/** Item name from the cache, filled on the client thread. */
	String itemName(int itemId)
	{
		String name = itemNames.get(itemId);
		if (name == null)
		{
			name = itemManager.getItemComposition(itemId).getName();
			itemNames.put(itemId, name);
		}
		return name;
	}

	ChestProgress getOpenChest()
	{
		return config.chestOverlay() || config.chestGlow() ? openChest : null;
	}

	/** Whether the numbers should be the solo ones right now. */
	private boolean solo()
	{
		if (!inRaid)
		{
			return needsTabSolo;
		}
		return raidSoloOverride != null ? raidSoloOverride : soloRaid;
	}

	/** The solo doses for the solo tab, or a solo raid, when they are kept apart. */
	private Needs needsFor(boolean solo)
	{
		return solo && config.separateSoloNeeds() ? needsSolo : needs;
	}

	private void leftRaid()
	{
		soloRaid = false;
		raidSoloOverride = null;
		openedWithByChest.clear();
		openedChests.clear();
		marking = false;
		privateItems.clear();
		roomKeys.clear();
		lastRoomSlot = null;
		currentChest = null;
		openChest = null;
		synchronized (lock)
		{
			privateStorage = null;
			sharedStorage = null;
		}
		inventoryDirty = true;
	}

	private static Supplies count(Item[] items)
	{
		int[] ids = new int[items.length];
		int[] quantities = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			ids[i] = items[i].getId();
			quantities[i] = items[i].getQuantity();
		}
		return Supplies.count(ids, quantities);
	}

	private static Supplies count(Map<Integer, Integer> items)
	{
		int[] ids = new int[items.size()];
		int[] quantities = new int[items.size()];
		int i = 0;
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			ids[i] = e.getKey();
			quantities[i++] = e.getValue();
		}
		return Supplies.count(ids, quantities);
	}

	private void recompute()
	{
		ItemContainer carried = client.getItemContainer(InventoryID.INV);
		Supplies carriedSupplies = carried == null ? Supplies.EMPTY : count(carried.getItems());
		Map<String, Integer> items = tally(carried);
		Map<String, Integer> worn = tally(client.getItemContainer(InventoryID.WORN));
		if (items == null)
		{
			items = Collections.emptyMap();
		}
		if (worn == null)
		{
			worn = Collections.emptyMap();
		}
		synchronized (lock)
		{
			inventory = carriedSupplies;
			inventoryItems = items;
			wornItems = worn;
		}
		updateOpenChest();
	}

	private static String name(PartyMember member)
	{
		String name = member.getDisplayName();
		return name == null || name.isEmpty() || "<unknown>".equals(name) ? "Unknown" : name;
	}

	// ---- party ----

	private void sendToParty()
	{
		ticksSinceSend++;
		if (!party.isInParty() || party.getLocalMember() == null)
		{
			lastSent = null;
			return;
		}
		if (ticksSinceSend < SEND_INTERVAL)
		{
			return;
		}
		CoxStorageMessage status;
		synchronized (lock)
		{
			status = new CoxStorageMessage(inventory.toArray(),
				privateStorage == null ? null : privateStorage.toArray(),
				sharedStorage == null ? null : sharedStorage.toArray());
		}
		if (resendStatus || !status.sameContent(lastSent))
		{
			resendStatus = false;
			lastSent = status;
			ticksSinceSend = 0;
			party.send(status);
		}
	}

	@Subscribe
	public void onCoxStorageMessage(CoxStorageMessage message)
	{
		PartyMember local = party.getLocalMember();
		if (local != null && local.getMemberId() == message.getMemberId())
		{
			// the party echoes our own messages; we already know
			return;
		}
		synchronized (lock)
		{
			members.put(message.getMemberId(), MemberSupplies.from(message));
		}
		refresh();
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		resendStatus = true;
		refresh();
	}

	@Subscribe
	public void onUserSync(UserSync event)
	{
		resendStatus = true;
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		synchronized (lock)
		{
			members.remove(event.getMemberId());
		}
		refresh();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		synchronized (lock)
		{
			members.clear();
		}
		resendStatus = true;
		refresh();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CoxStoragePlannerConfig.GROUP.equals(event.getGroup()))
		{
			if (CoxStoragePlannerConfig.KEY_SEPARATE_SOLO_CHESTS.equals(event.getKey()) && separateChests()
				&& chestsSolo.all().isEmpty() && !chests.all().isEmpty())
			{
				// start the solo set from the team plans rather than from nothing
				chestsSolo = chests.copy(gson);
				saveChests();
			}
			clientThread.invokeLater(this::updateOpenChest);
			refresh();
		}
	}

	// ---- sidebar actions, on the Swing thread ----

	@Override
	public void renameChest(String key, String name)
	{
		ChestPlan plan = book().get(key);
		if (plan != null && !plan.getName().equals(name.trim()))
		{
			plan.setName(name);
			saveChests();
			refresh();
		}
	}

	@Override
	public void setChestOrdered(String key, boolean ordered)
	{
		ChestPlan plan = book().get(key);
		if (plan != null && plan.isOrdered() != ordered)
		{
			plan.setOrdered(ordered);
			saveChests();
			clientThread.invokeLater(this::updateOpenChest);
			refresh();
		}
	}

	@Override
	public void setChestLines(String key, boolean deposit, String text)
	{
		ChestPlan plan = book().get(key);
		if (plan == null)
		{
			return;
		}
		List<String> lines = ChestPlan.lines(text);
		List<String> target = deposit ? plan.getDeposit() : plan.getWithdraw();
		if (!target.equals(lines))
		{
			target.clear();
			target.addAll(lines);
			saveChests();
			clientThread.invokeLater(this::updateOpenChest);
			refresh();
		}
	}

	@Override
	public void copyLoadout(String key)
	{
		clientThread.invokeLater(() ->
		{
			ChestPlan plan = book().get(key);
			if (plan == null)
			{
				return;
			}
			List<String> lines = new ArrayList<>();
			for (int containerId : new int[]{InventoryID.WORN, InventoryID.INV})
			{
				ItemContainer container = client.getItemContainer(containerId);
				if (container == null)
				{
					continue;
				}
				List<String> names = new ArrayList<>();
				List<Integer> quantities = new ArrayList<>();
				for (Item item : container.getItems())
				{
					names.add(item.getId() > 0 ? itemName(item.getId()) : null);
					quantities.add(item.getQuantity());
				}
				lines.addAll(ChestProgress.loadoutLines(names, quantities, containerId == InventoryID.WORN ? "wear " : ""));
			}
			if (lines.isEmpty())
			{
				return;
			}
			plan.getWithdraw().clear();
			plan.getWithdraw().addAll(lines);
			plan.setOrdered(true);
			if (plan.getDeposit().isEmpty())
			{
				// clear out whatever the loadout doesn't have before pulling it
				plan.getDeposit().add(ChestPlan.EVERYTHING_ELSE);
			}
			saveChests();
			updateOpenChest();
			refresh();
		});
	}

	@Override
	public void setMarking(boolean on)
	{
		if (marking != on)
		{
			marking = on;
			refresh();
		}
	}

	@Override
	public void selectChest(String key)
	{
		selectedChest = key;
	}

	@Override
	public void copyChestFromOther(String key)
	{
		ChestBook from = book() == chests ? chestsSolo : chests;
		ChestPlan source = from.get(key);
		ChestPlan plan = book().getOrCreate(key, chestName(key));
		if (source == null || plan == null)
		{
			return;
		}
		plan.setName(source.getName());
		plan.setOrdered(source.isOrdered());
		plan.getDeposit().clear();
		plan.getDeposit().addAll(source.getDeposit());
		plan.getWithdraw().clear();
		plan.getWithdraw().addAll(source.getWithdraw());
		saveChests();
		clientThread.invokeLater(this::updateOpenChest);
		refresh();
	}

	@Override
	public void deleteChest(String key)
	{
		if (book().remove(key))
		{
			saveChests();
			clientThread.invokeLater(this::updateOpenChest);
			refresh();
		}
	}

	@Override
	public void setNeed(Potion potion, int doses)
	{
		Needs plan = needsFor(needsTabSolo);
		if (plan.set(potion, doses))
		{
			configManager.setConfiguration(CoxStoragePlannerConfig.GROUP,
				plan == needsSolo ? CoxStoragePlannerConfig.KEY_NEEDS_SOLO : CoxStoragePlannerConfig.KEY_NEEDS, plan.encode());
			refresh();
		}
	}

	@Override
	public void setNeedsTab(boolean solo)
	{
		if (inRaid)
		{
			// in a raid the switch overrides the party size, say to run the solo chests in a team of two
			raidSoloOverride = solo == soloRaid ? null : solo;
			clientThread.invokeLater(this::updateOpenChest);
			refresh();
			return;
		}
		if (needsTabSolo != solo)
		{
			needsTabSolo = solo;
			configManager.setConfiguration(CoxStoragePlannerConfig.GROUP, CoxStoragePlannerConfig.KEY_NEEDS_TAB_SOLO, solo);
			refresh();
		}
	}

	// ---- drawing ----

	/** Pushes the current state to the sidebar. Safe from any thread. */
	private void refresh()
	{
		CoxStoragePanel target = panel;
		if (target == null)
		{
			return;
		}
		PanelState state = snapshot();
		SwingUtilities.invokeLater(() -> target.update(state));
	}

	private PanelState snapshot()
	{
		PanelState state = new PanelState();
		state.inParty = party.isInParty();
		state.countShared = config.countShared();
		state.countSplit = config.countSplit();
		state.units = config.needUnits();
		state.chests = book().copy(gson);
		state.currentChest = currentChest;
		state.marking = marking;
		state.putBack = config.chestPutBack();
		state.openChest = openChest != null || currentChest == null ? openChest : progressFor(currentChest);
		state.separateSoloNeeds = config.separateSoloNeeds();
		state.separateSoloChests = separateChests();
		state.trackStamina = config.trackStamina();
		state.solo = solo();
		state.inRaid = inRaid;
		Needs needs = needsFor(state.solo);
		for (Potion potion : Potion.values())
		{
			state.need.put(potion, state.applies(potion) ? needs.get(potion) : 0);
		}

		PartyMember local = party.getLocalMember();
		List<PartyMember> partyMembers = state.inParty ? party.getMembers() : Collections.emptyList();

		synchronized (lock)
		{
			state.carriedItems = inventoryItems;
			state.wornItems = wornItems;
			state.inventory = inventory;
			state.privateStorage = privateStorage;
			state.sharedStorage = sharedStorage;
			MemberSupplies mine = new MemberSupplies(inventory, privateStorage, sharedStorage);
			for (PartyMember member : partyMembers)
			{
				PanelState.Member view = new PanelState.Member();
				view.name = name(member);
				view.self = local != null && local.getMemberId() == member.getMemberId();
				view.status = view.self ? mine : members.get(member.getMemberId());
				state.team.add(view);
			}
		}
		return state;
	}
}

package com.coxstorageplanner;

/** How dose counts are shown and typed in the sidebar. Everything is stored as doses. */
public enum NeedUnits
{
	DOSES("Doses", "doses"),
	POTIONS("Potions", "potions");

	private final String displayName;
	private final String word;

	NeedUnits(String displayName, String word)
	{
		this.displayName = displayName;
		this.word = word;
	}

	/** The unit word after a number. */
	public String getWord()
	{
		return word;
	}

	/** A dose count in these units: 9 doses is "9" or "2.25". */
	public String format(int doses)
	{
		if (this == DOSES || doses % Potion.DOSES_PER_POTION == 0)
		{
			return String.valueOf(doses / (this == DOSES ? 1 : Potion.DOSES_PER_POTION));
		}
		String text = String.valueOf(doses / (double) Potion.DOSES_PER_POTION);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}

	/** Doses for something typed in these units, 0 for anything that isn't a number. */
	public int parse(String text)
	{
		try
		{
			double value = Double.parseDouble(text.trim());
			return (int) Math.round(this == DOSES ? value : value * Potion.DOSES_PER_POTION);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.coxstorageplanner;

/**
 * The raid potions. Every raid potion has 12 consecutive item ids:
 * (-) 1-4 dose, regular 1-4 dose, (+) 1-4 dose.
 * The supply potions get a row in the sidebar totals. Elder, twisted and kodai are only counted
 * as the three parts of a split overload, which is what Vanguards drop one set of.
 * Stamina is brought from outside for the running at a solo Olm and only matters in a solo raid.
 */
public enum Potion
{
	OVERLOAD("Overload", "Ovl", Ids.raid(20985), true, true, false),
	XERICS_AID("Xeric's aid", "Aid", Ids.raid(20973), true, true, false),
	REVITALISATION("Revitalisation", "Revit", Ids.raid(20949), true, true, false),
	PRAYER_ENHANCE("Prayer enhance", "Enh", Ids.raid(20961), true, true, false),
	STAMINA("Stamina", "Stam", new int[]{12631, 12629, 12627, 12625}, true, false, true),
	ELDER("Elder", "Elder", Ids.raid(20913), false, false, false),
	TWISTED("Twisted", "Twisted", Ids.raid(20925), false, false, false),
	KODAI("Kodai", "Kodai", Ids.raid(20937), false, false, false),
	/** One elder, one twisted and one kodai, claimed together. Not an item of its own. */
	SPLIT_OVERLOAD("Split overload", "Split", new int[0], false, true, false);

	public static final int DOSES_PER_POTION = 4;

	private static final class Ids
	{
		/** The 12 ids of a raid potion, starting at the (-) 1 dose. */
		private static int[] raid(int first)
		{
			int[] ids = new int[3 * DOSES_PER_POTION];
			for (int i = 0; i < ids.length; i++)
			{
				ids[i] = first + i;
			}
			return ids;
		}
	}

	private final String displayName;
	private final String shortName;
	/** Item ids, the one at index i holding i % 4 + 1 doses. */
	private final int[] itemIds;
	private final boolean supply;
	private final boolean claimable;
	private final boolean soloOnly;

	Potion(String displayName, String shortName, int[] itemIds, boolean supply, boolean claimable, boolean soloOnly)
	{
		this.displayName = displayName;
		this.shortName = shortName;
		this.itemIds = itemIds;
		this.supply = supply;
		this.claimable = claimable;
		this.soloOnly = soloOnly;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getShortName()
	{
		return shortName;
	}

	/** Whether the sidebar totals and the "needed" settings cover this potion. */
	public boolean isSupply()
	{
		return supply;
	}

	/** Whether rooms drop it as something to claim. */
	public boolean isClaimable()
	{
		return claimable;
	}

	/** Whether it only counts in a solo raid. */
	public boolean isSoloOnly()
	{
		return soloOnly;
	}

	/** Item id of the full potion, used for the sidebar icon. */
	public int getIconItemId()
	{
		return itemIds.length == 0 ? -1 : itemIds[itemIds.length - 1];
	}

	public boolean matches(int itemId)
	{
		return doses(itemId) > 0;
	}

	/** Doses in one item with this id, 0 if it isn't this potion. */
	public int doses(int itemId)
	{
		for (int i = 0; i < itemIds.length; i++)
		{
			if (itemIds[i] == itemId)
			{
				return i % DOSES_PER_POTION + 1;
			}
		}
		return 0;
	}

	public static Potion of(int itemId)
	{
		for (Potion potion : values())
		{
			if (potion.matches(itemId))
			{
				return potion;
			}
		}
		return null;
	}
}

package com.coxstorageplanner;

/** What one party member last told us they hold. */
public final class MemberSupplies
{
	/** inventory only */
	private final Supplies carried;
	/** null until they open their private storage */
	private final Supplies stored;
	/** null until someone opens the shared storage */
	private final Supplies shared;

	public MemberSupplies(Supplies carried, Supplies stored, Supplies shared)
	{
		this.carried = carried;
		this.stored = stored;
		this.shared = shared;
	}

	public static MemberSupplies from(CoxStorageMessage message)
	{
		return new MemberSupplies(Supplies.of(message.getCarried()),
			message.getStored() == null ? null : Supplies.of(message.getStored()),
			message.getShared() == null ? null : Supplies.of(message.getShared()));
	}

	public Supplies getCarried()
	{
		return carried;
	}

	public Supplies getStored()
	{
		return stored;
	}

	public Supplies getShared()
	{
		return shared;
	}

	/** Inventory plus private storage as far as it is known. */
	public Supplies getHeld()
	{
		return stored == null ? carried : carried.plus(stored);
	}
}

package com.coxstorageplanner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** The steps for the chest you have open, ticked off as the inventory changes. */
class ChestOverlay extends OverlayPanel
{
	private static final Color DONE = new Color(110, 200, 110);
	private static final Color NEXT = new Color(255, 220, 90);
	private static final Color TODO = Color.WHITE;
	private static final Color SKIPPED = new Color(160, 160, 160);

	private final CoxStoragePlannerPlugin plugin;
	private final CoxStoragePlannerConfig config;

	@Inject
	ChestOverlay(CoxStoragePlannerPlugin plugin, CoxStoragePlannerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.chestOverlay())
		{
			return null;
		}
		ChestProgress progress = plugin.getOpenChest();
		if (progress == null || (progress.wears.isEmpty() && progress.deposits.isEmpty() && progress.withdrawals.isEmpty()))
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(progress.plan.getName().isEmpty() ? "Chest" : progress.plan.getName())
			.color(progress.isDone() ? DONE : TODO)
			.build());
		ChestProgress.Step next = progress.next();
		int width = 0;
		for (ChestProgress.Step step : progress.wears)
		{
			width = Math.max(width, line(graphics, "Wear", step, false));
		}
		for (ChestProgress.Step step : progress.deposits)
		{
			width = Math.max(width, line(graphics, "Put in", step, false));
		}
		for (String name : progress.outOfOrder)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Put back").leftColor(TODO).right(name).rightColor(TODO).build());
			width = Math.max(width, graphics.getFontMetrics().stringWidth("Put back  " + name));
		}
		for (ChestProgress.Step step : progress.withdrawals)
		{
			width = Math.max(width, line(graphics, progress.plan.isOrdered() ? step.order + "." : "Take", step, step == next));
		}
		panelComponent.setPreferredSize(new Dimension(width + 20, 0));
		return super.render(graphics);
	}

	private int line(Graphics2D graphics, String left, ChestProgress.Step step, boolean next)
	{
		String right = (step.missing ? "– " : step.done ? "✓ " : "") + step.line.text + (step.missing ? " (not here)" : "");
		Color color = step.missing ? SKIPPED : step.done ? DONE : next ? NEXT : TODO;
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.leftColor(color)
			.right(right)
			.rightColor(color)
			.build());
		return graphics.getFontMetrics().stringWidth(left + "  " + right);
	}
}

package com.coxstorageplanner;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Every chest plan, in the order the chests were first opened. Stored as a JSON list. */
public final class ChestBook
{
	public static final int MAX_CHESTS = 40;

	private final Map<String, ChestPlan> chests = new LinkedHashMap<>();

	public static ChestBook parse(String json, Gson gson)
	{
		ChestBook book = new ChestBook();
		if (json == null || json.isEmpty())
		{
			return book;
		}
		try
		{
			List<ChestPlan> plans = gson.fromJson(json, new TypeToken<List<ChestPlan>>()
			{
			}.getType());
			if (plans != null)
			{
				for (ChestPlan plan : plans)
				{
					if (plan != null && plan.getKey() != null && book.chests.size() < MAX_CHESTS)
					{
						book.chests.put(plan.getKey(), plan);
					}
				}
			}
		}
		catch (JsonSyntaxException e)
		{
			// a broken config entry: start over rather than crash
		}
		return book;
	}

	public synchronized String encode(Gson gson)
	{
		return gson.toJson(new ArrayList<>(chests.values()));
	}

	public synchronized ChestPlan get(String key)
	{
		return key == null ? null : chests.get(key);
	}

	/** The plan for a key, made with the given name if there wasn't one. Null when full. */
	public synchronized ChestPlan getOrCreate(String key, String name)
	{
		ChestPlan plan = chests.get(key);
		if (plan == null && chests.size() < MAX_CHESTS)
		{
			plan = new ChestPlan(key, name);
			chests.put(key, plan);
		}
		return plan;
	}

	public synchronized boolean remove(String key)
	{
		return chests.remove(key) != null;
	}

	public synchronized List<ChestPlan> all()
	{
		return Collections.unmodifiableList(new ArrayList<>(chests.values()));
	}

	/** Deep copy for a snapshot the Swing thread can read while the plans change. */
	public synchronized ChestBook copy(Gson gson)
	{
		return parse(encode(gson), gson);
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A snapshot of everything the sidebar shows, built by the plugin and drawn on the Swing thread. */
final class PanelState
{
	static final class Member
	{
		String name;
		boolean self;
		/** null until the member's plugin has sent something */
		MemberSupplies status;
	}

	boolean inParty;
	boolean countShared;
	boolean countSplit;

	Supplies inventory = Supplies.EMPTY;
	/** null until the storage has been opened this raid */
	Supplies privateStorage;
	Supplies sharedStorage;
	final Map<Potion, Integer> need = new EnumMap<>(Potion.class);
	/** Whether the numbers are for a solo raid: the raid's size while in one, the tab otherwise. */
	boolean solo;
	/** Whether the player is in a raid, when the Team | Solo switch overrides the party size instead of being saved. */
	boolean inRaid;
	boolean separateSoloNeeds;
	/** Whether solo raids have their own chest plans, so {@link #chests} is the set for {@link #solo}. */
	boolean separateSoloChests;
	boolean trackStamina;
	NeedUnits units = NeedUnits.POTIONS;
	ChestBook chests = new ChestBook();
	/** Chest of the room the player is in, null outside one. */
	String currentChest;
	/** Item name to quantity in the inventory, for the steps of a chest that isn't open. */
	Map<String, Integer> carriedItems = new LinkedHashMap<>();
	/** Item name to quantity worn, which counts as withdrawn. */
	Map<String, Integer> wornItems = new LinkedHashMap<>();
	/** Progress at the storage that's open right now, null when none is. */
	ChestProgress openChest;
	/** Whether clicking items in a storage or the inventory adds them to the chest's lists. */
	boolean marking;
	/** Whether an ordered plan wants carried items of later steps put back first. */
	boolean putBack;

	final List<Member> team = new ArrayList<>();

	/** Everything within reach: inventory, private storage, and shared storage if that counts. */
	private Supplies held()
	{
		Supplies held = inventory;
		if (privateStorage != null)
		{
			held = held.plus(privateStorage);
		}
		Supplies shared = shared();
		if (countShared && shared != null)
		{
			held = held.plus(shared);
		}
		return held;
	}

	/** The shared storage as you saw it, or as a party member did if you haven't opened it. */
	Supplies shared()
	{
		if (sharedStorage != null)
		{
			return sharedStorage;
		}
		for (Member member : team)
		{
			if (member.status != null && member.status.getShared() != null)
			{
				return member.status.getShared();
			}
		}
		return null;
	}

	/** Overload doses you hold as sets of elder, twisted and kodai. */
	int splitHeld()
	{
		return held().splitOverloadDoses();
	}

	/** Doses that count towards what you need. */
	int have(Potion potion)
	{
		int have = held().doses(potion);
		if (potion == Potion.OVERLOAD && countSplit)
		{
			have += splitHeld();
		}
		return have;
	}

	int shortfall(Potion potion)
	{
		return Math.max(0, need.getOrDefault(potion, 0) - have(potion));
	}

	/** Whether the supply row for this potion applies right now. */
	boolean applies(Potion potion)
	{
		return potion.isSupply() && (!potion.isSoloOnly() || (solo && trackStamina));
	}

	/** "Xeric's aid 8 doses, Stamina 1 potion" for everything short, empty when nothing is. */
	String shortfalls()
	{
		StringBuilder text = new StringBuilder();
		for (Potion potion : Potion.values())
		{
			int shortfall = applies(potion) ? shortfall(potion) : 0;
			if (shortfall > 0)
			{
				text.append(text.length() == 0 ? "" : ", ").append(potion.getDisplayName()).append(' ')
					.append(units.format(shortfall)).append(' ').append(units.getWord());
			}
		}
		return text.toString();
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Doses you want to have when you get to Olm, per potion. Stored as "POTION:doses,...".
 * Nothing set at all is stored as "none" so it isn't mistaken for "never set".
 */
public final class Needs
{
	public static final int MAX_DOSES = 99;
	private static final String NONE = "none";

	private final Map<Potion, Integer> doses = new EnumMap<>(Potion.class);

	/** A first plan for a team. */
	public static Needs defaults()
	{
		Needs needs = new Needs();
		needs.set(Potion.OVERLOAD, 4);
		needs.set(Potion.XERICS_AID, 24);
		needs.set(Potion.REVITALISATION, 12);
		needs.set(Potion.PRAYER_ENHANCE, 4);
		return needs;
	}

	/** A first plan for a solo: more running, so a stamina and another revitalisation. */
	public static Needs soloDefaults()
	{
		Needs needs = defaults();
		needs.set(Potion.REVITALISATION, 16);
		needs.set(Potion.STAMINA, 4);
		return needs;
	}

	/** The given defaults for something never stored, otherwise whatever parses. */
	public static Needs parse(String encoded, Needs defaults)
	{
		if (encoded == null || encoded.isEmpty())
		{
			return defaults;
		}
		Needs needs = new Needs();
		for (String entry : encoded.split(","))
		{
			String[] parts = entry.split(":");
			try
			{
				if (parts.length == 2)
				{
					needs.set(Potion.valueOf(parts[0]), Integer.parseInt(parts[1]));
				}
				else if (parts.length == 3)
				{
					// the per-room form of 1.0.0: add the rooms up
					Potion potion = Potion.valueOf(parts[1]);
					needs.set(potion, needs.get(potion) + Integer.parseInt(parts[2]));
				}
			}
			catch (IllegalArgumentException e)
			{
				// an entry from another version
			}
		}
		return needs;
	}

	public synchronized String encode()
	{
		List<String> entries = new ArrayList<>();
		for (Map.Entry<Potion, Integer> e : doses.entrySet())
		{
			if (e.getValue() > 0)
			{
				entries.add(e.getKey().name() + ":" + e.getValue());
			}
		}
		return entries.isEmpty() ? NONE : String.join(",", entries);
	}

	public synchronized Needs copy()
	{
		return parse(encode(), new Needs());
	}

	public synchronized int get(Potion potion)
	{
		return doses.getOrDefault(potion, 0);
	}

	/** @return whether anything changed */
	public synchronized boolean set(Potion potion, int count)
	{
		count = Math.max(0, Math.min(MAX_DOSES, count));
		if (get(potion) == count)
		{
			return false;
		}
		doses.put(potion, count);
		return true;
	}
}
